def merge_cli(cover_path, out_path):
    if find_tool("pdfunite") and find_tool("pdfinfo"):
        n = _pdfinfo_pages()
        subprocess.run([find_tool("pdfunite"), cover_path, INPUT_PDF, out_path],
                       check=True, capture_output=True)
        return n, "pdfunite"
    if find_tool("mutool"):
        n = _pdfinfo_pages() if find_tool("pdfinfo") else None
        subprocess.run([find_tool("mutool"), "merge", "-o", out_path,
                        cover_path, INPUT_PDF], check=True, capture_output=True)
        if n is None:
            raise SystemExit("mutool found but no pdfinfo for page count")
        return n, "mutool"
    if find_tool("qpdf"):
        n = int(subprocess.run([find_tool("qpdf"), "--show-npages", INPUT_PDF],
                               check=True, capture_output=True, text=True).stdout.strip())
        subprocess.run([find_tool("qpdf"), "--empty", "--pages", cover_path,
                        INPUT_PDF, "--", out_path], check=True, capture_output=True)
        return n, "qpdf"
    if find_tool("pdftk"):
        n = subprocess.run([find_tool("pdftk"), INPUT_PDF, "dump_data"],
                           check=True, capture_output=True, text=True).stdout
        n = max(int(m) for m in re.findall(r"NumberOfPages: (\d+)", n))
        subprocess.run([find_tool("pdftk"), cover_path, INPUT_PDF, "cat", "output", out_path],
                       check=True, capture_output=True)
        return n, "pdftk"
    if find_tool("gs"):
        n = subprocess.run([find_tool("gs"), "-q", "-dNODISPLAY", "-c",
                            f"({INPUT_PDF}) (r) file runpdfbegin pdfpagecount = quit"],
                           check=True, capture_output=True, text=True).stdout.strip()
        subprocess.run([find_tool("gs"), "-q", "-dNOPAUSE", "-dBATCH", "-sDEVICE=pdfwrite",
                        "-sOutputFile=" + out_path, cover_path, INPUT_PDF],
                       check=True, capture_output=True)
        return int(n), "gs"
    return None


def _pdfinfo_pages():
    out = subprocess.run([find_tool("pdfinfo"), INPUT_PDF], check=True,
                         capture_output=True, text=True).stdout
    m = re.search(r"Pages:\s+(\d+)", out)
    return int(m.group(1))


# ------------------------------------------------------------ manual merge
def tokenize(b):
    """Minimal PDF tokenizer returning (tokens, next_index)."""
    toks = []
    n = len(b)
    i = 0
    while i < n:
        c = b[i]
        if c in b" \t\r\n\f":
            i += 1
        elif b.startswith(b"<<", i):
            inner, i = tokenize(b, i + 2)
            toks.append(("dict", inner))
            i += 2
        elif b.startswith(b">>", i):
            return toks, i + 2
        elif c == ord(b"["):
            inner, i = tokenize(b, i + 1)
            toks.append(("array", inner))
        elif c == ord(b"]"):
            return toks, i + 1
        elif c == ord(b"/"):
            j = i + 1
            while j < n and b[j] not in b" \t\r\n\f/<>[]()":
                j += 1
            toks.append(b[i:j])
            i = j
        elif c == ord(b"("):
            depth = 1
            j = i + 1
            while j < n and depth:
                if b[j] == ord(b"\\"):
                    j += 2
                    continue
                if b[j] == ord(b"("):
                    depth += 1
                elif b[j] == ord(b")"):
                    depth -= 1
                j += 1
            toks.append(b[i:j])
            i = j
        elif c == ord(b"<"):
            j = b.find(b">", i)
            toks.append(b[i:j + 1])
            i = j + 1
        elif c in b"0123456789+-.":
            m = re.match(rb"-?\d+(?:\.\d+)?", b[i:])
            toks.append(m.group(0))
            i += len(m.group(0))
        else:
            j = i
            while j < n and b[j] not in b" \t\r\n\f/<>[]()":
                j += 1
            toks.append(b[i:j])
            i = j
    return toks, i


def resolve_refs(toks):
    out = []
    i = 0
    while i < len(toks):
        t = toks[i]
        if (isinstance(t, bytes) and re.fullmatch(rb"\d+", t)
                and i + 2 < len(toks)
                and isinstance(toks[i + 1], bytes) and re.fullmatch(rb"\d+", toks[i + 1])
                and toks[i + 2] == b"R"):
            out.append(("ref", int(t), int(toks[i + 1])))
            i += 3
        else:
            out.append(t)
            i += 1
    return out


def to_value(t):
    if isinstance(t, tuple) and t and t[0] == "ref":
        return (t[1], t[2])
    if isinstance(t, tuple) and t and t[0] == "array":
        return [to_value(x) for x in t[1]]
    if isinstance(t, tuple) and t and t[0] == "dict":
        return to_dict(t[1])
    if isinstance(t, bytes):
        if re.fullmatch(rb"-?\d+", t):
            return int(t)
        if re.fullmatch(rb"-?\d+\.\d+", t):
            return float(t)
        if t == b"true":
            return True
        if t == b"false":
            return False
        if t == b"null":
            return None
    return t


def to_dict(toks):
    d = {}
    i = 0
    while i < len(toks):
        k = toks[i]
        if isinstance(k, bytes) and k.startswith(b"/") and i + 1 < len(toks):
            d[k] = to_value(toks[i + 1])
            i += 2
        else:
            i += 1
    return d


def extract_dict(raw):
    """Return the dictionary text portion of a raw object."""
    m = re.search(rb"obj", raw)
    if not m:
        return b""
    pos = m.end()
    sm = re.search(rb"stream", raw[pos:])
    em = re.search(rb"endobj", raw[pos:])
    if sm and (em is None or sm.start() < em.start()):
        return raw[pos:pos + sm.start()]
    if em:
        return raw[pos:pos + em.start()]
    return raw[pos:]


def object_dict(raw):
    toks, _ = tokenize(extract_dict(raw))
    toks = resolve_refs(toks)
    for t in toks:
        if isinstance(t, tuple) and t and t[0] == "dict":
            return to_dict(t[1])
    return {}


def object_bytes_at(data, off):
    """Return raw bytes of the object starting at off (verbatim)."""
    m = re.match(rb"\s*(\d+)\s+(\d+)\s+obj", data[off:off + 64])
    if not m:
        return None
    pos = off + m.end()
    stream_m = re.search(rb"stream\r?\n|stream\n", data[pos:pos + 8192])
    end_m = re.search(rb"endobj", data[pos:pos + 8192])
    if stream_m and (end_m is None or stream_m.start() < end_m.start()):
        s_start = pos + stream_m.end()
        dict_text = data[pos:pos + stream_m.start()]
        lm = re.search(rb"/Length\s+(\d+)", dict_text)
        if lm:
            length = int(lm.group(1))
            e = data.find(b"endstream", s_start + length)
        else:
            e = data.find(b"endstream", s_start)
        if e == -1:
            return None
        e2 = data.find(b"endobj", e)
        if e2 == -1:
            return None
        return data[off:e2 + 6]
    if end_m:
        return data[off:pos + end_m.end()]
    return None


def parse_objects(data):
    objs = {}
    gens = {}
    for m in re.finditer(rb"(\d+)\s+(\d+)\s+obj\b", data):
        num = int(m.group(1))
        gen = int(m.group(2))
        if num in objs:
            continue
        raw = object_bytes_at(data, m.start())
        if raw is not None:
            objs[num] = raw
            gens[num] = gen
    return objs, gens


def serialize(v):
    if isinstance(v, tuple):  # (num, gen) reference
        return b"%d %d R" % v
    if isinstance(v, bool):
        return b"true" if v else b"false"
    if isinstance(v, int):
        return b"%d" % v
    if isinstance(v, float):
        return b"%f" % v
    if isinstance(v, bytes):
        if v.startswith(b"/"):
            return v
        return (b"(" + v.replace(b"\\", b"\\\\").replace(b"(", b"\\(")
                .replace(b")", b"\\)") + b")")
    if isinstance(v, list):
        return b"[" + b" ".join(serialize(x) for x in v) + b"]"
    if isinstance(v, dict):
        parts = []
        for k, val in v.items():
            parts.append(k + b" " + serialize(val))
        return b"<< " + b" ".join(parts) + b" >>"
    return b"null"


def merge_manual(cover_path, out_path):
    data = open(INPUT_PDF, "rb").read()
    if not data.startswith(b"%PDF"):
        raise SystemExit("report.pdf does not look like a PDF file")

    objs, gens = parse_objects(data)
    print(f"[manual] parsed {len(objs)} objects from {INPUT_PDF}")

    # Detect object streams (compressed objects) - informational.
    objstm = [n for n, raw in objs.items()
              if object_dict(raw).get(b"/Type") == b"/ObjStm"]
    if objstm:
        print(f"[manual] WARNING: {len(objstm)} object stream(s) present; "
              f"objects stored inside them are not materialized")

    # Locate catalog via trailer / xref-stream dictionary.
    sm = re.search(rb"startxref\s+(\d+)", data)
    if not sm:
        raise SystemExit("no startxref found in report.pdf")
    xref_off = int(sm.group(1))
    seg = data[xref_off:xref_off + 32].lstrip()
    if seg.startswith(b"xref"):
        tm = re.search(rb"trailer\s*(<<.*?>>)", data[xref_off:], re.S)
        if not tm:
            raise SystemExit("no trailer dictionary found")
        trailer = object_dict(b"0 0 obj\n" + tm.group(1))
    else:
        raw = object_bytes_at(data, xref_off)
        if raw is None:
            raise SystemExit("could not read xref stream object")
        trailer = object_dict(raw)
    root_ref = trailer.get(b"/Root")
    if not root_ref:
        raise SystemExit("no /Root in trailer")

    catalog = object_dict(objs[root_ref[0]])
    pages_ref = catalog.get(b"/Pages")
    if not pages_ref:
        raise SystemExit("no /Pages in catalog")
    pages_num = pages_ref[0]

    # Walk the page tree.
    page_nums = []
    inherited = {}
    seen = set()

    def walk(num):
        if num in seen:
            return
        seen.add(num)
        raw = objs.get(num)
        if raw is None:
            raise SystemExit(f"missing page-tree object {num}")
        d = object_dict(raw)
        if b"/Kids" in d:
            if not inherited:
                for k in (b"/MediaBox", b"/CropBox", b"/Rotate", b"/Resources", b"/UserUnit"):
                    if k in d:
                        inherited[k] = d[k]
            for ref in d.get(b"/Kids", []):
                walk(ref[0])
        else:
            page_nums.append(num)

    walk(pages_num)
    if not page_nums:
        raise SystemExit("no pages found in report.pdf")
    print(f"[manual] original pages: {len(page_nums)} (objects {page_nums})")

    # ---- build the merged document ----
    max_num = max(objs.keys())
    new_catalog = max_num + 1
    new_pages_root = max_num + 2
    cover_page = max_num + 3
    cover_font1 = max_num + 4
    cover_font2 = max_num + 5
    cover_contents = max_num + 6
    last_num = cover_contents

    def esc(s):
        return s.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")

    content = (
        "BT\n/F1 28 Tf\n306 436 Td\n(%s) Tj\n"
        "/F2 16 Tf\n0 -36 Td\n(%s) Tj\nET\n"
    ) % (esc(TITLE), esc(DATE_STR)).encode("latin-1")

    cover_page_raw = (b"%d 0 obj\n<< /Type /Page /Parent %d 0 R /MediaBox [0 0 612 792] "
                      b"/Resources << /Font << /F1 %d 0 R /F2 %d 0 R >> >> /Contents %d 0 R >>\nendobj\n"
                      % (cover_page, new_pages_root, cover_font1, cover_font2, cover_contents))
    font1_raw = (b"%d 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>\nendobj\n"
                 % cover_font1)
    font2_raw = (b"%d 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n"
                 % cover_font2)
    contents_raw = (b"%d 0 obj\n<< /Length %d >>\nstream\n%s\nendstream\nendobj\n"
                    % (cover_contents, len(content), content))

    kids = b" ".join([b"%d 0 R" % cover_page] + [b"%d 0 R" % n for n in page_nums])
    attrs_b = b"".join(k + b" " + serialize(v) + b"\n" for k, v in inherited.items())
    pages_root_raw = (b"%d 0 obj\n<< /Type /Pages /Kids [%s] /Count %d\n%s>>\nendobj\n"
                      % (new_pages_root, kids, len(page_nums) + 1, attrs_b))
    catalog_raw = (b"%d 0 obj\n<< /Type /Catalog /Pages %d 0 R >>\nendobj\n"
                   % (new_catalog, new_pages_root))

    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = {}
    new_gens = {}

    def emit(num, raw, gen=0):
        offsets[num] = len(out)
        new_gens[num] = gen
        out += raw

    emit(new_catalog, catalog_raw)
    emit(new_pages_root, pages_root_raw)
    emit(cover_page, cover_page_raw)
    emit(cover_font1, font1_raw)
    emit(cover_font2, font2_raw)
    emit(cover_contents, contents_raw)

    parent_pat = re.compile(rb"(/Parent\s+)\d+\s+\d+\s+R")
    for num in sorted(objs):
        raw = objs[num]
        if num in page_nums:
            raw = parent_pat.sub(rb"\g<1>%d 0 R" % new_pages_root, raw)
        emit(num, raw, gens.get(num, 0))

    xref_pos = len(out)
    out += b"xref\n0 %d\n" % (last_num + 1)
    out += b"0000000000 65535 f \n"
    for num in range(1, last_num + 1):
        if num in offsets:
            out += b"%010d %05d n \n" % (offsets[num], new_gens[num])
        else:
            out += b"0000000000 00000 f \n"
    out += (b"trailer\n<< /Size %d /Root %d 0 R >>\nstartxref\n%d\n%%%%EOF\n"
            % (last_num + 1, new_catalog, xref_pos))

    with open(out_path, "wb") as fh:
        fh.write(bytes(out))
    return len(page_nums)


def merge(cover_path, out_path):
    for fn in (merge_pypdf, merge_pypdf2, merge_pypdf3, merge_pypdf4,
               merge_fitz, merge_pikepdf, merge_pdfrw):
        try:
            return fn(cover_path, out_path), fn.__name__
        except ImportError:
            continue
    res = merge_cli(cover_path, out_path)
    if res is not None:
        return res
    return merge_manual(cover_path, out_path), "manual-merge"


# ----------------------------------------------------------------- validation
def validate(original_pages):
    data = open(INPUT_PDF, "rb").read()
    if not data.startswith(b"%PDF"):
        raise AssertionError("report.pdf no longer starts with %PDF")
    page_objs = re.findall(rb"/Type\s*/Page[^s]", data)
    if len(page_objs) != original_pages + 1:
        raise AssertionError(
            f"Expected {original_pages + 1} page objects, found {len(page_objs)}")

    def esc_bytes(s):
        return s.replace(b"\\", b"\\\\").replace(b"(", b"\\(").replace(b")", b"\\)")

    if esc_bytes(TITLE.encode("latin-1")) not in data:
        raise AssertionError("Cover title bytes not found in report.pdf")
    if esc_bytes(DATE_STR.encode("latin-1")) not in data:
        raise AssertionError("Current date bytes not found in report.pdf")
    return len(page_objs)


def main():
    if not os.path.exists(INPUT_PDF):
        raise SystemExit(f"Missing input file: {INPUT_PDF}")

    fd, cover_path = tempfile.mkstemp(suffix="_cover.pdf", dir=".")
    os.close(fd)
    fd2, out_path = tempfile.mkstemp(suffix="_merged.pdf", dir=".")
    os.close(fd2)
    try:
        cover_src = make_cover(cover_path)
        original_pages, merge_src = merge(cover_path, out_path)
        os.replace(out_path, INPUT_PDF)
        total = validate(original_pages)
    finally:
        for p in (cover_path, out_path):
            if os.path.exists(p):
                os.unlink(p)

    print(f"OK: report.pdf now has {total} pages (was {original_pages}).")
    print(f"Cover page: '{TITLE}' / '{DATE_STR}' (cover built with {cover_src}, "
          f"merged with {merge_src}).")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Task-local helper: prepend a dated cover page to report.pdf.

Adds a cover page with the exact title "Annual Financial Report" and the
operator runtime current date as the first page of report.pdf, preserving all
existing pages in order. Only report.pdf and task-scoped temp files are touched.

Strategy (stdlib only): first try installed PDF libraries or CLI tools; if none
exist, perform a manual object-level merge of report.pdf.
"""

import os
import re
import shutil
import subprocess
import sys
import tempfile
from datetime import date

INPUT_PDF = "report.pdf"
TITLE = "Annual Financial Report"
DATE_STR = date.today().strftime("%B %d, %Y")

CANDIDATE_DIRS = [
    "/usr/bin", "/usr/local/bin", "/opt/homebrew/bin", "/bin", "/usr/sbin",
    "/opt/bin", "/opt/poppler/bin", "/usr/lib/poppler/bin", "/opt/mupdf/bin",
]


def find_tool(name):
    p = shutil.which(name)
    if p:
        return p
    for d in CANDIDATE_DIRS:
        q = os.path.join(d, name)
        if os.path.isfile(q) and os.access(q, os.X_OK):
            return q
    return None


# ---------------------------------------------------------------- cover page
def make_cover_reportlab(path):
    from reportlab.lib.pagesizes import letter
    from reportlab.pdfgen import canvas

    width, height = letter
    c = canvas.Canvas(path, pagesize=letter)
    c.setFont("Helvetica-Bold", 28)
    c.drawCentredString(width / 2, height / 2 + 40, TITLE)
    c.setFont("Helvetica", 16)
    c.drawCentredString(width / 2, height / 2 - 20, DATE_STR)
    c.showPage()
    c.save()


def make_cover_manual(path):
    """Stdlib-only fallback: hand-built US Letter cover PDF."""
    def esc(s):
        return s.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")

    content = (
        "BT\n/F1 28 Tf\n306 436 Td\n(%s) Tj\n"
        "/F2 16 Tf\n0 -36 Td\n(%s) Tj\nET\n"
    ) % (esc(TITLE), esc(DATE_STR))

    obj_texts = [
        b"<< /Type /Catalog /Pages 2 0 R >>",
        b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] "
        b"/Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>",
        b"<< /Length %d >>\nstream\n%s\nendstream" % (len(content), content.encode("latin-1")),
    ]

    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = []
    for i, body in enumerate(obj_texts, start=1):
        offsets.append(len(out))
        out += b"%d 0 obj\n" % i + body + b"\nendobj\n"
    xref_pos = len(out)
    n = len(obj_texts) + 1
    out += b"xref\n0 %d\n" % n
    out += b"0000000000 65535 f \n"
    for off in offsets:
        out += b"%010d 00000 n \n" % off
    out += b"trailer\n<< /Size %d /Root 1 0 R >>\nstartxref\n%d\n%%%%EOF\n" % (n, xref_pos)
    with open(path, "wb") as fh:
        fh.write(bytes(out))


def make_cover(path):
    try:
        make_cover_reportlab(path)
        return "reportlab"
    except ImportError:
        make_cover_manual(path)
        return "manual"


# -------------------------------------------------------------------- merging
def merge_pypdf(cover_path, out_path):
    from pypdf import PdfReader, PdfWriter
    reader = PdfReader(INPUT_PDF)
    writer = PdfWriter()
    writer.add_page(PdfReader(cover_path).pages[0])
    for page in reader.pages:
        writer.add_page(page)
    with open(out_path, "wb") as fh:
        writer.write(fh)
    return len(reader.pages)


def merge_pypdf2(cover_path, out_path):
    from PyPDF2 import PdfReader, PdfWriter
    reader = PdfReader(INPUT_PDF)
    writer = PdfWriter()
    writer.add_page(PdfReader(cover_path).pages[0])
    for page in reader.pages:
        writer.add_page(page)
    with open(out_path, "wb") as fh:
        writer.write(fh)
    return len(reader.pages)


def merge_pypdf3(cover_path, out_path):
    from PyPDF3 import PdfFileReader, PdfFileWriter
    reader = PdfFileReader(INPUT_PDF)
    writer = PdfFileWriter()
    writer.addPage(PdfFileReader(cover_path).getPage(0))
    for i in range(reader.getNumPages()):
        writer.addPage(reader.getPage(i))
    with open(out_path, "wb") as fh:
        writer.write(fh)
    return reader.getNumPages()


def merge_pypdf4(cover_path, out_path):
    from PyPDF4 import PdfFileReader, PdfFileWriter
    reader = PdfFileReader(INPUT_PDF)
    writer = PdfFileWriter()
    writer.addPage(PdfFileReader(cover_path).getPage(0))
    for i in range(reader.getNumPages()):
        writer.addPage(reader.getPage(i))
    with open(out_path, "wb") as fh:
